// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {W_WALLET, Log} from "../src/W_WALLET.sol";

uint256 constant VALUE_CAP = 1000000000000000000000000000000;

contract InvMutTest is Test {
    W_WALLET c;
    function setUp() public { c = new W_WALLET(address(new Log())); }

    function testFuzz_property(uint256 futureT, address actor, uint256 value) public {
        vm.assume(value <= VALUE_CAP);
        vm.assume(actor != address(0));
        vm.assume(futureT > block.timestamp && futureT < type(uint256).max);
        vm.assume(value > 0);
        vm.deal(actor, value);

        vm.prank(actor);
        c.Put{value: value}(futureT);

        // General rule: after a Put specifying a future unlock time, the stored
        // unlockTime is that future time and is never in the past.
        assertTrue(__invmut_c_Acc_unlockTime(actor) >= block.timestamp);
    }

    function __invmut_c_Acc_unlockTime(address __k) internal view returns (uint256) {
        (uint256 _v0, ) = c.Acc(__k);
        return _v0;
    }
}
